import express from 'express';

const app = express();

// 1. Rota raiz: devolve TEXTO.
//    res.send percebe que é string e escolhe o formato de texto sozinho.
app.get('/', (req, res) => {
  res.send('Olá, aluno!');
});

// 2. Rota de API: devolve um OBJETO.
//    res.send percebe que é objeto e envia JSON.
//    (res.json faz a mesma coisa de forma explícita.)
app.get('/api/usuario', (req, res) => {
  const usuario = { nome: 'Ana', nivel: 3 };
  res.send(usuario);
});

// 3. Liga o servidor e avisa no terminal.
//    O log ajuda: é aqui que você vê que o servidor subiu.
app.listen(3000, () => {
  console.log('servidor ouvindo na porta 3000');
});
